void MischeAlles()
{
    while (Kann("erz", "kristall"))
        Robot.Mischen("erz", "kristall");
    while (Kann("moos", "wasser"))
        Robot.Mischen("moos", "wasser");
    while (Kann("biogel", "legierung"))
        Robot.Mischen("biogel", "legierung");
}

void Station(string feld)
{
    if (feld == "labor")
        MischeAlles();
    else if (feld != "boden")
        Robot.Aufheben();
}

