void Sammle(string feld)
{
    if (feld == "quelle")
    {
        while (Anzahl("wasser") < bedarf["wasser"])
            Robot.Aufheben();
    }
    else if (bedarf.ContainsKey(feld) && Anzahl(feld) < bedarf[feld])
        Robot.Aufheben();
}

